``` sas
 /* Get acceleration factor in a data step */
 data acf;
   set coeff;
   af=exp(estimate);
   lowercl=exp(estimate);
   uppercl=exp(estimate);
   format _all_ 8.4;
 run;

 proc print data=acf noobs;
  title 'Acceleration factor';
 run;

```


